from pathlib import Path
import json
P=Path(__file__).parent/'public'
# Original geometry: two independent paths converge into an intentionally open doorway.
shape='<path d="M7 28L16 9h8v19M41 28L32 9h-8" fill="none" stroke="{color}" stroke-width="4" stroke-linecap="square" stroke-linejoin="miter"/>'
for name,color,bg in [('symbol','#111820',''),('symbol-mono','#111820',''),('symbol-reversed','#f4f1ea','<rect width="48" height="40" fill="#111820"/>')]:
    (P/'brand'/f'{name}.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 40" role="img" aria-label="VESPRA open doorway symbol">'+bg+shape.format(color=color)+'</svg>')
# Editable geometric vector wordmark; no proprietary font embedded or required.
glyphs={'V':'M0 0L10 30 20 0','E':'M20 0H0V30H20M0 15H15','S':'M20 0H0V15H20V30H0','P':'M0 30V0H20V15H0','R':'M0 30V0H20V15H0M10 15L22 30','A':'M0 30L10 0 20 30M4 20H16'}
for suffix,color,bg in [('', '#111820',''),('-reversed','#f4f1ea','<rect width="222" height="50" fill="#111820"/>')]:
    body=''.join(f'<path transform="translate({12+i*34},10)" d="{glyphs[c]}"/>' for i,c in enumerate('VESPRA'))
    (P/'brand'/f'wordmark{suffix}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 222 50" role="img" aria-label="VESPRA">{bg}<g fill="none" stroke="{color}" stroke-width="2.4" stroke-linecap="square" stroke-linejoin="miter">{body}</g></svg>')
(P/'brand'/'app-icon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1024 1024"><rect width="1024" height="1024" rx="220" fill="#111820"/><g transform="translate(112 175) scale(16.66)">'+shape.format(color='#d8f275')+'</g></svg>')
(P/'manifest.webmanifest').write_text(json.dumps({'name':'VESPRA Demo','short_name':'VESPRA','start_url':'/','display':'standalone','background_color':'#111820','theme_color':'#111820','icons':[{'src':'/brand/app-icon.svg','sizes':'any','type':'image/svg+xml','purpose':'any'}]}))

def lum(hex):
    channels=[int(hex[i:i+2],16)/255 for i in (1,3,5)]
    return sum(w*(x/12.92 if x<=.04045 else ((x+.055)/1.055)**2.4) for w,x in zip((.2126,.7152,.0722),channels))
pairs=[]
for theme,text,muted,bg,surface,success,warning,error in [('light','#111820','#52606d','#f4f1ea','#fffdf8','#216343','#805400','#a32638'),('dark','#f4f1ea','#b7c2cc','#111820','#1d2731','#93d8b0','#f5ca7a','#ff9da8')]:
    for label,fg in [('text',text),('muted',muted),('success',success),('warning',warning),('error',error)]:
        for background in (bg,surface):pairs.append((theme+' '+label,fg,background))
pairs += [('primary','#111820','#d8f275'),('inverse','#f4f1ea','#111820'),('promo muted','#b7c2cc','#111820'),('promo eyebrow','#d8f275','#111820'),('avatar label','#111820','#f4f1ea')]
rows=[]
for label,fg,bg in pairs:
    ratio=(max(lum(fg),lum(bg))+.05)/(min(lum(fg),lum(bg))+.05)
    assert ratio>=4.5,(label,ratio)
    rows.append(f'| {label} | {fg} | {bg} | {ratio:.2f}:1 | Pass |')
(Path(__file__).parent/'docs'/'contrast.md').write_text('# Actual text pairings\n\nGenerated by `python3 build_assets.py`. WCAG AA normal text threshold: 4.5:1. Decorative borders are not text; additional manual non-text and focus checks remain.\n\n| Use | Foreground | Background | Contrast | AA |\n|---|---|---|---|---|\n'+'\n'.join(rows)+'\n')
borders=[]
for label,fg,background in [('light control border','#7d8789','#f4f1ea'),('light control border','#7d8789','#fffdf8'),('dark control border','#788695','#111820'),('dark control border','#788695','#1d2731')]:
    ratio=(max(lum(fg),lum(background))+.05)/(min(lum(fg),lum(background))+.05)
    assert ratio>=3.0,(label,ratio)
    borders.append(f'| {label} | {fg} | {background} | {ratio:.2f}:1 | Pass |')
report=Path(__file__).parent/'docs'/'contrast.md'
with report.open('a') as out:out.write('\n\n## Input/control boundaries · 3:1 threshold\n\n| Use | Foreground | Background | Contrast | Non-text AA |\n|---|---|---|---|---|\n'+'\n'.join(borders)+'\n')
print(f'Original SVGs and manifest generated; {len(rows)} text and {len(borders)} control-boundary contrast pairings passed.')
